        except Exception as e:
            print(f"Source read error: {e}", file=sys.stderr)

        # 7. Read the aot decode_mla source (first 80 lines)
        print("\n=== DECODE_MLA SOURCE (first 80 lines) ===", file=sys.stderr)
        try:
            import aiter.aot.triton.decode_mla as dm
            with open(dm.__file__) as f:
